// Package module routes the Cryptoki signature entry points to in-process
// ML-DSA when the key object carries its own material.
//
// A post-quantum key pair is generated by this module rather than by the
// backend (module_keygen_quantum.go says why), so the seed and the public key
// live in CKA_VALUE on the two objects and no daemon holds a key the module
// could name. The transport's SignRequest addresses a key by CKA_ID-derived
// KeyID and describes it with a hash, a padding and a salt length; none of
// those describe an ML-DSA signature, and there is no key on the far end to
// address. An ML-DSA operation on such an object must therefore run here.
//
// Two entry points reach this file:
//
//   - C_Sign / C_Verify and their multi-part forms, through the quantumSign*
//     and quantumVerify* methods on Module. Each returns a "handled" flag: a
//     classical key, or a post-quantum key that does name a backend key,
//     returns false and the caller proceeds down the transport path unchanged.
//   - C_VerifySignature (signature-first verification, v3.2 §5.15.7), through
//     verifySigInit and verifySigVerify.
//
// References:
//   - OASIS PKCS#11 v3.2 §5.13 (signing), §5.15 (verification), §6.67 (ML-DSA)
//   - NIST FIPS 204 (ML-DSA)
package module

// mldsaSignatureVendorMechanism maps a resolved ML-DSA security level to the
// per-level vendor mechanism the QuantumCryptoManager dispatches signing and
// verification against.
//
// It is the ML-DSA analog of mlkemEncapsulateVendorMechanism: the v3.2
// standard CKM_ML_DSA names no level, so it is resolved to one of these before
// reaching QuantumSignInit or QuantumVerifyInit, whose security-level lookup is
// written against the per-level mechanisms.
var mldsaSignatureVendorMechanism = map[int]MechanismType{
	44: CKM_VENDOR_ML_DSA_44,
	65: CKM_VENDOR_ML_DSA_65,
	87: CKM_VENDOR_ML_DSA_87,
}

// mldsaLevelByParameterSet reads a CKA_PARAMETER_SET value as an ML-DSA
// security level. Parameter set values are scoped per algorithm (v3.2 §2.3),
// so this table must never be consulted for an ML-KEM key.
var mldsaLevelByParameterSet = map[ParameterSetType]int{
	CKP_ML_DSA_44: 44,
	CKP_ML_DSA_65: 65,
	CKP_ML_DSA_87: 87,
}

// resolveMLDSALevel determines the concrete ML-DSA security level (44, 65 or
// 87) for an operation naming the v3.2 standard CKM_ML_DSA mechanism, which
// per §6.67.4 carries no mechanism parameter and takes its parameter set from
// the key object.
//
// CKA_PARAMETER_SET is authoritative. fallbackLen is consulted only when the
// object carries no readable parameter set, and only a FIPS 204 public key
// length resolves: this module stores every ML-DSA private key as a 32-byte
// seed regardless of level, so a private key's own length says nothing.
//
// Unlike the ML-KEM analog (resolveMLKEMLevel) there is no baseline level to
// fall back on. ML-KEM-768 is a mandatory parameter set and a wrong guess is
// caught immediately by a ciphertext that fails to decapsulate; an ML-DSA seed
// expanded at the wrong level yields a well-formed signature that no verifier
// on earth accepts, so an unresolvable level must be an error rather than a
// guess. Zero says it could not be resolved.
func resolveMLDSALevel(keyObj *Object, fallbackLen int) int {
	if parameterSet, ok := parameterSetFromAttributeValue(keyObj.GetAttribute(CKA_PARAMETER_SET)); ok {
		if level, known := mldsaLevelByParameterSet[parameterSet]; known {
			return level
		}
	}
	switch fallbackLen {
	case MLDSA44PublicKeySize:
		return 44
	case MLDSA65PublicKeySize:
		return 65
	case MLDSA87PublicKeySize:
		return 87
	default:
		return 0
	}
}

// resolveMLDSADispatchMechanism returns the mechanism to dispatch to the
// QuantumCryptoManager with. CKM_ML_DSA resolves to the per-level vendor
// mechanism its key object's parameter set names; a per-level mechanism the
// caller named itself passes through unchanged.
//
// The code for an unresolvable parameter set is CKR_MECHANISM_PARAM_INVALID,
// matching resolveKEMDispatchMechanism so the two post-quantum families answer
// the same condition the same way. It is in the return table of C_SignInit
// (§5.13.1) and C_VerifyInit (§5.15.1).
func resolveMLDSADispatchMechanism(mechanism *Mechanism, keyObj *Object, fallbackLen int) (*Mechanism, error) {
	if mechanism.Type != CKM_ML_DSA {
		return mechanism, nil
	}
	level := resolveMLDSALevel(keyObj, fallbackLen)
	vendorType, ok := mldsaSignatureVendorMechanism[level]
	if !ok {
		return nil, NewPKCS11ErrorWithMessage(
			CKR_MECHANISM_PARAM_INVALID, "unable to resolve ML-DSA parameter set")
	}
	return &Mechanism{
		Type:           vendorType,
		Parameter:      mechanism.Parameter,
		TypedParameter: mechanism.TypedParameter,
	}, nil
}

// holdsOwnQuantumSignatureMaterial reports whether an ML-DSA operation on this
// key object must run in process.
//
// The test is that the mechanism is ML-DSA and the object names no backend key.
// A key this token generated carries an empty KeyID because there is nothing on
// the far end to name, and its material is in CKA_VALUE; a key that does carry
// a KeyID is addressable by the transport and is left to it, so a backend that
// grows ML-DSA support later needs no change here.
//
// The empty-KeyID case must be claimed even when CKA_VALUE is missing, rather
// than falling through. Falling through is what sent an ML-DSA C_Sign to the
// transport under KeyID="", where the daemon matched a key whose CN is the
// empty string; the module has to answer for a key with no material itself, and
// CKR_KEY_HANDLE_INVALID is what quantumSignInit answers with.
func holdsOwnQuantumSignatureMaterial(mechanism *Mechanism, keyObj *Object) bool {
	return mechanism != nil && keyObj != nil &&
		IsMLDSAMechanism(mechanism.Type) && keyObj.KeyID == ""
}

// quantumCryptoManager type-asserts the module's build-tag-gated quantumCrypto
// field, the same shape kemEncapsulate and verifySigInit use.
func (m *Module) quantumCryptoManager() (*QuantumCryptoManager, bool) {
	qcm, ok := m.quantumCrypto.(*QuantumCryptoManager)
	return qcm, ok && qcm != nil
}

// quantumSignInit completes C_SignInit for a key that holds its own ML-DSA
// material, storing a QuantumSignOperation where the transport path would have
// stored a SignOperation.
//
// The first return value reports whether this path claimed the request. False
// means the caller must continue down the transport path; the CK_RV is only
// meaningful when it is true.
//
// The session's operation slot has already been claimed by
// SessionManager.InitializeOperation when this runs, so the operation state
// exists to attach the crypto operation to; a caller that gets a non-CKR_OK
// answer here must finalize it, exactly as it does for a transport-path
// failure.
func (m *Module) quantumSignInit(session *Session, mechanism *Mechanism, keyHandle ObjectHandle, keyObj *Object) (bool, CK_RV) {
	if !holdsOwnQuantumSignatureMaterial(mechanism, keyObj) {
		return false, CKR_OK
	}

	qcm, ok := m.quantumCryptoManager()
	if !ok {
		return true, CKR_MECHANISM_INVALID
	}

	// The seed is copied out of the object store: QuantumSignOperation holds
	// the slice for the life of the operation, and the store's own copy must
	// not be reachable from it.
	seed := copyBytes(keyObj.GetAttribute(CKA_VALUE))
	if len(seed) == 0 {
		return true, CKR_KEY_HANDLE_INVALID
	}

	dispatch, resolveErr := resolveMLDSADispatchMechanism(mechanism, keyObj, len(seed))
	if resolveErr != nil {
		return true, FromError(resolveErr)
	}

	op, initErr := qcm.QuantumSignInit(dispatch, keyHandle, keyObj.KeyID, keyObj.BackendName, seed)
	if initErr != nil {
		return true, FromError(initErr)
	}

	opState := session.GetOperationByType(OperationSign)
	if opState == nil {
		return true, CKR_OPERATION_NOT_INITIALIZED
	}
	opState.CryptoOp = op
	session.SetOperationByType(OperationSign, opState)

	return true, CKR_OK
}

// quantumSign completes C_Sign for an operation quantumSignInit established.
//
// It claims the call by the type of the stored crypto operation rather than by
// re-examining the key, so a signature is produced by the very operation
// C_SignInit built and cannot be rebuilt here under a different parameter set.
//
// The result is cached and the operation left active, matching the two-call
// convention the transport path follows (v3.2 §5.2): the caller confirms
// receipt with C_FinishOperation.
func (m *Module) quantumSign(session *Session, opState *OperationState, data []byte) ([]byte, bool, CK_RV) {
	op, ok := opState.CryptoOp.(*QuantumSignOperation)
	if !ok || op == nil {
		return nil, false, CKR_OK
	}

	qcm, ok := m.quantumCryptoManager()
	if !ok {
		return nil, true, CKR_MECHANISM_INVALID
	}

	signature, signErr := qcm.QuantumSign(op, data)
	if signErr != nil {
		return nil, true, FromError(signErr)
	}

	cacheResult(session, OperationSign, signature)
	return signature, true, CKR_OK
}

// quantumSignUpdate completes C_SignUpdate for an in-process ML-DSA operation.
//
// ML-DSA signs the message itself rather than a digest of it (FIPS 204 §5.2),
// so a multi-part operation accumulates the parts and signs them at
// C_SignFinal. MultiPart is set for the same reason the transport path sets it:
// C_Sign must refuse to terminate an operation that has been fed parts.
func (m *Module) quantumSignUpdate(session *Session, opState *OperationState, data []byte) (bool, CK_RV) {
	op, ok := opState.CryptoOp.(*QuantumSignOperation)
	if !ok || op == nil {
		return false, CKR_OK
	}

	qcm, ok := m.quantumCryptoManager()
	if !ok {
		return true, CKR_MECHANISM_INVALID
	}

	if updateErr := qcm.QuantumSignUpdate(op, data); updateErr != nil {
		return true, FromError(updateErr)
	}

	opState.MultiPart = true
	opState.CryptoOp = op
	session.SetOperationState(*opState)

	return true, CKR_OK
}

// quantumSignFinal completes C_SignFinal for an in-process ML-DSA operation,
// signing everything C_SignUpdate accumulated.
func (m *Module) quantumSignFinal(session *Session, opState *OperationState) ([]byte, bool, CK_RV) {
	op, ok := opState.CryptoOp.(*QuantumSignOperation)
	if !ok || op == nil {
		return nil, false, CKR_OK
	}

	qcm, ok := m.quantumCryptoManager()
	if !ok {
		return nil, true, CKR_MECHANISM_INVALID
	}

	signature, signErr := qcm.QuantumSignFinal(op)
	if signErr != nil {
		return nil, true, FromError(signErr)
	}

	cacheResult(session, OperationSign, signature)
	return signature, true, CKR_OK
}

// quantumVerifyInit completes C_VerifyInit for a public key that holds its own
// ML-DSA material, and is the exact counterpart of quantumSignInit.
func (m *Module) quantumVerifyInit(session *Session, mechanism *Mechanism, keyHandle ObjectHandle, keyObj *Object) (bool, CK_RV) {
	if !holdsOwnQuantumSignatureMaterial(mechanism, keyObj) {
		return false, CKR_OK
	}

	qcm, ok := m.quantumCryptoManager()
	if !ok {
		return true, CKR_MECHANISM_INVALID
	}

	publicKey := copyBytes(keyObj.GetAttribute(CKA_VALUE))
	if len(publicKey) == 0 {
		return true, CKR_KEY_HANDLE_INVALID
	}

	dispatch, resolveErr := resolveMLDSADispatchMechanism(mechanism, keyObj, len(publicKey))
	if resolveErr != nil {
		return true, FromError(resolveErr)
	}

	op, initErr := qcm.QuantumVerifyInit(dispatch, keyHandle, keyObj.KeyID, keyObj.BackendName, publicKey)
	if initErr != nil {
		return true, FromError(initErr)
	}

	opState := session.GetOperationByType(OperationVerify)
	if opState == nil {
		return true, CKR_OPERATION_NOT_INITIALIZED
	}
	opState.CryptoOp = op
	session.SetOperationByType(OperationVerify, opState)

	return true, CKR_OK
}

// quantumVerify completes C_Verify for an operation quantumVerifyInit
// established. Unlike signing there is nothing to cache: C_Verify's whole
// answer is its return value, and the caller terminates the operation.
func (m *Module) quantumVerify(opState *OperationState, data, signature []byte) (bool, CK_RV) {
	op, ok := opState.CryptoOp.(*QuantumVerifyOperation)
	if !ok || op == nil {
		return false, CKR_OK
	}

	qcm, ok := m.quantumCryptoManager()
	if !ok {
		return true, CKR_MECHANISM_INVALID
	}

	if verifyErr := qcm.QuantumVerify(op, data, signature); verifyErr != nil {
		return true, FromError(verifyErr)
	}
	return true, CKR_OK
}

// quantumVerifyUpdate completes C_VerifyUpdate for an in-process ML-DSA
// operation, accumulating a part of the message.
func (m *Module) quantumVerifyUpdate(session *Session, opState *OperationState, data []byte) (bool, CK_RV) {
	op, ok := opState.CryptoOp.(*QuantumVerifyOperation)
	if !ok || op == nil {
		return false, CKR_OK
	}

	qcm, ok := m.quantumCryptoManager()
	if !ok {
		return true, CKR_MECHANISM_INVALID
	}

	if updateErr := qcm.QuantumVerifyUpdate(op, data); updateErr != nil {
		return true, FromError(updateErr)
	}

	opState.MultiPart = true
	opState.CryptoOp = op
	session.SetOperationState(*opState)

	return true, CKR_OK
}

// quantumVerifyFinal completes C_VerifyFinal for an in-process ML-DSA
// operation, verifying the signature against everything C_VerifyUpdate
// accumulated.
func (m *Module) quantumVerifyFinal(opState *OperationState, signature []byte) (bool, CK_RV) {
	op, ok := opState.CryptoOp.(*QuantumVerifyOperation)
	if !ok || op == nil {
		return false, CKR_OK
	}

	qcm, ok := m.quantumCryptoManager()
	if !ok {
		return true, CKR_MECHANISM_INVALID
	}

	if verifyErr := qcm.QuantumVerifyFinal(op, signature); verifyErr != nil {
		return true, FromError(verifyErr)
	}
	return true, CKR_OK
}

// verifySigInit initializes a quantum signature-first verification operation
// by delegating to QuantumCryptoManager.QuantumVerifyInit.
//
// Parameters:
//   - quantumCrypto: the Module's quantumCrypto field (typed as any)
//   - mech: the PKCS#11 mechanism for verification
//   - keyHandle: the object handle of the verification key
//   - publicKey: the raw public key bytes (CKA_VALUE from the key object)
//
// Returns:
//   - interface{}: the initialized QuantumVerifyOperation (stored in session CryptoOp)
//   - error: nil on success, or a PKCS11Error
func verifySigInit(quantumCrypto any, mech *Mechanism, keyHandle ObjectHandle, publicKey []byte) (interface{}, error) {
	qcm, ok := quantumCrypto.(*QuantumCryptoManager)
	if !ok || qcm == nil {
		return nil, NewPKCS11Error(CKR_MECHANISM_INVALID)
	}
	return qcm.QuantumVerifyInit(mech, keyHandle, "verifysig", "quantum", publicKey)
}

// verifySigVerify performs quantum signature-first verification by delegating to
// QuantumCryptoManager.QuantumVerify.
//
// Parameters:
//   - quantumCrypto: the Module's quantumCrypto field (typed as any)
//   - op: the QuantumVerifyOperation initialized by verifySigInit
//   - data: the data to verify the signature against
//   - signature: the signature (provided at init time for signature-first flow)
//
// Returns:
//   - error: nil if the signature is valid, CKR_SIGNATURE_INVALID if not, or another PKCS11Error
func verifySigVerify(quantumCrypto any, op interface{}, data, signature []byte) error {
	qcm, ok := quantumCrypto.(*QuantumCryptoManager)
	if !ok || qcm == nil {
		return NewPKCS11Error(CKR_MECHANISM_INVALID)
	}
	verifyOp, ok := op.(*QuantumVerifyOperation)
	if !ok {
		return NewPKCS11Error(CKR_OPERATION_NOT_INITIALIZED)
	}
	return qcm.QuantumVerify(verifyOp, data, signature)
}
